-- Repoint every Base44-hosted file reference at Supabase Storage.
--
-- The migration off Base44 copied file URLs rather than the files themselves,
-- so layer geometry and meter source files were still being fetched from
-- base44.app at runtime — the app kept working only because Base44 was still
-- serving them. All 114 files have been copied into the project-files
-- bucket under migrated/ and verified byte-identical to their originals before
-- this migration runs.
--
-- The mapping is kept rather than dropped: it is the record of what was
-- rewritten, and makes the change reversible by swapping the update columns.

create table if not exists public.base44_url_migration (
  old_url text primary key,
  new_url text not null,
  migrated_at timestamptz not null default now()
);

-- No policies: this is operational history, not application data, so it stays
-- unreadable through PostgREST while remaining available to the service role.
alter table public.base44_url_migration enable row level security;

on conflict (old_url) do nothing;

update public.project_layer l
   set file_url = m.new_url
  from public.base44_url_migration m
 where l.file_url = m.old_url;

update public.project_layer l
   set icon_url = m.new_url
  from public.base44_url_migration m
 where l.icon_url = m.old_url;

update public.meter t
   set source_file_url = m.new_url
  from public.base44_url_migration m
 where t.source_file_url = m.old_url;

update public.import_log t
   set source_file_url = m.new_url
  from public.base44_url_migration m
 where t.source_file_url = m.old_url;

update public.image_overlay t
   set file_url = m.new_url
  from public.base44_url_migration m
 where t.file_url = m.old_url;
